    padding: 80px 120px 40px;
    text-align: center;
    flex-shrink: 0;
  }

  .unicef-badge {
    display: inline-block;
    background: rgba(255,255,255,0.15);
    border: 2px solid rgba(255,255,255,0.3);
    border-radius: 50px;
    padding: 12px 36px;
    color: #fff;
    font-size: 22px;
    font-weight: 700;
    letter-spacing: 4px;
    text-transform: uppercase;
    margin-bottom: 40px;
  }

  .header h1 {
    font-size: 96px;
    font-weight: 900;
    color: #fff;
    line-height: 1.05;
    margin-bottom: 24px;
    text-shadow: 0 4px 20px rgba(0,0,0,0.15);
  }

  .header .subtitle {
    font-size: 30px;
    color: rgba(255,255,255,0.85);
    max-width: 1400px;
    margin: 0 auto;
    line-height: 1.5;
    font-weight: 400;
  }

  /* Big stat hero */
  .hero-stat {
    padding: 50px 120px 40px;
    text-align: center;
    flex-shrink: 0;
  }

  .stat-number {
    font-size: 200px;
    font-weight: 900;
    color: #F7C948;
    text-shadow: 0 6px 30px rgba(0,0,0,0.2);
    line-height: 1;
    margin-bottom: 8px;
  }

  .stat-unit {
    font-size: 80px;
    font-weight: 900;
    color: #F7C948;
    text-shadow: 0 4px 20px rgba(0,0,0,0.15);
  }

  .stat-label {
    font-size: 36px;
    color: rgba(255,255,255,0.9);
    font-weight: 600;
    margin-top: 12px;
    letter-spacing: 1px;
  }

  /* Secondary stats row */
  .stats-row {
    display: flex;
    justify-content: center;
    gap: 60px;
    padding: 30px 120px 50px;
    flex-shrink: 0;
  }

  .mini-stat {
    text-align: center;
    background: rgba(255,255,255,0.1);
    border: 1px solid rgba(255,255,255,0.2);
    border-radius: 24px;
    padding: 32px 48px;
    min-width: 280px;
  }

  .mini-stat .num {
    font-size: 64px;
    font-weight: 900;
    color: #F7C948;
    line-height: 1.1;
  }

  .mini-stat .lbl {
    font-size: 18px;
    color: rgba(255,255,255,0.85);
    font-weight: 500;
    margin-top: 8px;
    line-height: 1.4;
  }

  /* Divider */
  .divider {
    width: 200px;
    height: 4px;
    background: rgba(255,255,255,0.3);
    margin: 0 auto;
    border-radius: 2px;
  }

  /* Barriers section */
  .barriers-section {
    padding: 50px 120px 40px;
    flex-shrink: 0;
  }

  .section-title {
    font-size: 48px;
    font-weight: 800;
    color: #fff;
    text-align: center;
    margin-bottom: 40px;
  }

  .barriers-grid {
    display: flex;
    justify-content: center;
    gap: 32px;
    flex-wrap: wrap;
  }

  .barrier-card {
    background: rgba(255,255,255,0.12);
    border: 1px solid rgba(255,255,255,0.18);
