    padding: 40px 32px;
    width: 380px;
    text-align: center;
    backdrop-filter: blur(10px);
  }

  .barrier-icon {
    width: 72px;
    height: 72px;
    border-radius: 50%;
    background: rgba(247,201,72,0.2);
    display: flex;
    align-items: center;
    justify-content: center;
    margin: 0 auto 20px;
    font-size: 36px;
  }

  .barrier-card h3 {
    font-size: 26px;
    font-weight: 800;
    color: #F7C948;
    margin-bottom: 12px;
  }

  .barrier-card p {
    font-size: 18px;
    color: rgba(255,255,255,0.82);
    line-height: 1.55;
  }

  /* Focus Areas with Infographic */
  .focus-section {
    padding: 40px 100px;
    flex-shrink: 0;
  }

  .infographic-container {
    background: #ffffff;
    border-radius: 28px;
    padding: 20px;
    box-shadow: 0 8px 40px rgba(0,0,0,0.15);
    height: 520px;
    overflow: hidden;
  }

  .infographic-container > div {
    width: 100%;
    height: 100%;
  }

  /* Call to action */
  .cta-section {
    padding: 40px 120px 50px;
    text-align: center;
    flex-shrink: 0;
  }

  .cta-box {
    background: linear-gradient(135deg, #F5A623 0%, #F7C948 100%);
    border-radius: 32px;
    padding: 56px 80px;
    max-width: 1800px;
    margin: 0 auto;
    box-shadow: 0 8px 40px rgba(0,0,0,0.15);
  }

  .cta-box h2 {
    font-size: 52px;
    font-weight: 900;
    color: #004B87;
    margin-bottom: 20px;
  }

  .cta-box p {
    font-size: 26px;
    color: #1a3a5c;
    line-height: 1.6;
    max-width: 1400px;
    margin: 0 auto 28px;
    font-weight: 500;
  }

  .cta-pill {
    display: inline-block;
    background: #004B87;
    color: #F7C948;
    font-size: 28px;
    font-weight: 800;
    padding: 18px 56px;
    border-radius: 50px;
    letter-spacing: 1px;
  }

  /* SDG badge */
  .sdg-row {
    display: flex;
    justify-content: center;
    align-items: center;
    gap: 20px;
    margin-top: 28px;
  }

  .sdg-badge {
    background: #004B87;
    color: #fff;
    font-size: 18px;
    font-weight: 700;
    padding: 10px 28px;
    border-radius: 40px;
  }

  /* Footer */
  .footer {
    padding: 24px 120px;
    text-align: center;
    flex-shrink: 0;
    margin-top: auto;
  }

  .footer p {
    font-size: 16px;
    color: rgba(255,255,255,0.5);
  }

  /* Bottom accent */
  .bottom-bar {
    height: 12px;
    background: linear-gradient(90deg, #F5A623, #F7C948, #F5A623);
    flex-shrink: 0;
  }
</style>
