<div class="poster">

  <div class="top-bar"></div>

  <div class="header">
    <div class="unicef-badge">UNICEF &bull; Education For All</div>
    <h1>Every Child Deserves<br>to Learn</h1>
    <p class="subtitle">Education is a fundamental right — yet millions of children are denied it due to conflict, poverty, discrimination, and systemic failures.</p>
  </div>

  <div class="hero-stat">
    <div class="stat-number">250</div>
    <div class="stat-unit">MILLION</div>
    <div class="stat-label">children and adolescents are out of school worldwide</div>
  </div>

  <div class="stats-row">
    <div class="mini-stat">
      <div class="num">70%</div>
      <div class="lbl">of children in low-income<br>countries cannot read<br>by age 10</div>
    </div>
    <div class="mini-stat">
      <div class="num">2.5×</div>
      <div class="lbl">girls in crisis settings<br>more likely to be<br>out of school</div>
    </div>
    <div class="mini-stat">
      <div class="num">~49%</div>
      <div class="lbl">of children with<br>disabilities never<br>attend school</div>
    </div>
    <div class="mini-stat">
      <div class="num">190+</div>
      <div class="lbl">countries where<br>UNICEF runs education<br>programmes</div>
    </div>
  </div>

  <div class="divider"></div>

  <div class="barriers-section">
    <div class="section-title">Barriers Keeping Children Out of School</div>
    <div class="barriers-grid">
      <div class="barrier-card">
        <div class="barrier-icon">⚔️</div>
        <h3>Conflict</h3>
        <p>Schools destroyed, teachers displaced, and children traumatized by armed conflict and humanitarian emergencies.</p>
      </div>
      <div class="barrier-card">
        <div class="barrier-icon">💰</div>
        <h3>Poverty</h3>
        <p>Families cannot afford fees, uniforms, or supplies — and may rely on children for labour or income.</p>
      </div>
      <div class="barrier-card">
        <div class="barrier-icon">⚖️</div>
        <h3>Gender Inequality</h3>
        <p>Deep-rooted social norms continue to limit girls' access to education, especially at secondary level.</p>
      </div>
      <div class="barrier-card">
        <div class="barrier-icon">♿</div>
        <h3>Disability</h3>
        <p>Nearly half of children with disabilities in low-income countries never set foot in a classroom.</p>
      </div>
      <div class="barrier-card">
        <div class="barrier-icon">🌍</div>
        <h3>Climate Change</h3>
        <p>Floods, droughts, and extreme weather increasingly disrupt schooling for the most vulnerable children.</p>
      </div>
    </div>
  </div>

  <div class="focus-section">
    <div class="section-title">UNICEF's Education Focus Areas</div>
    <div class="infographic-container">
      <div id="container"></div>
    </div>
  </div>

  <div class="cta-section">
    <div class="cta-box">
      <h2>Every Child Left Behind Is a Missed Opportunity</h2>
      <p>Investing in education means investing in peace, innovation, and sustainable development. Together — governments, communities, organizations, and individuals — we can ensure no child is left behind.</p>
      <div class="cta-pill">ACT NOW — SUPPORT EDUCATION FOR ALL</div>
      <div class="sdg-row">
        <div class="sdg-badge">🎯 SDG 4: Quality Education</div>
        <div class="sdg-badge">🌐 unicef.org/education</div>
      </div>
    </div>
  </div>

  <div class="footer">
    <p>Source: UNICEF Education Programme (unicef.org/education) &bull; Data adapted for advocacy purposes</p>
  </div>

  <div class="bottom-bar"></div>
</div>

<script src="/app/vendor/infographic.min.js"></script>
<script>
const syntax = `infographic list-grid-badge-card
data
  title Key Focus Areas
  desc UNICEF's strategic pillars for transforming education worldwide
  lists
    - label Early Childhood
      desc Building strong foundations through pre-primary education
      icon baby
    - label Inclusive Education
      desc Ensuring children with disabilities can access school
      icon people community
    - label Gender Equality
      desc Removing barriers preventing girls from completing school
      icon heart
    - label Education in Emergencies
      desc Learning continuity for children in conflict zones
      icon shield
    - label Digital Learning
      desc Leveraging technology to expand access globally
      icon laptop computer
    - label Youth Skills
      desc Equipping adolescents for employment and civic life
      icon graduation cap
theme
  palette #00AEEF #0077C0 #F5A623 #F7C948 #004B87 #2ABFBF`;

const infographic = new AntVInfographic.Infographic({
  container: '#container',
  width: '100%',
  height: '100%',
});
infographic.render(syntax);
document.fonts?.ready.then(() => {
  infographic.render(syntax);
}).catch((error) => console.error('Font error:', error));
</script>
</body>
</html>
